    EXPECT_TRUE(deviceMoETransferSlotCopyComplete(transfer_slots[0], 1, 0, 0));
    EXPECT_EQ(transfer_slots[0].layer, 0u);
    EXPECT_EQ(transfer_slots[0].expert, 0u);
