    (void)hipMemcpy(d_weights, weights.data(), weights.size() * sizeof(float), hipMemcpyHostToDevice);
    (void)hipMemcpy(d_indices, token_indices.data(), token_indices.size() * sizeof(int), hipMemcpyHostToDevice);

