/**
 * @brief Prove one descriptor table may execute distinct source reduction trees.
 *
 * Expert overlay can place a compact Q4_K expert beside a compact Q5_K expert
 * (or beside its streamed expanded representation).  At this geometry their
 * generated serial-M1 policies use different K-partition counts.  The old ROCm
 * launcher collapsed the table to codebook 255 and tried to query that marker
 * as a real format.  This regression exercises both static-table and active-bank
 * production entrypoints and requires byte identity with serial decode.
 */
TEST(Test__ROCmMoEKernel,
     MixedCodebookDownDescriptorPoliciesMatchSerialDecodeBytes)
{
    SKIP_IF_NO_ROCM();

    constexpr int d_model = 128;
    constexpr int intermediate = 256;
    constexpr int num_experts = 2;
    constexpr int num_active = 2;
    constexpr int expert_ids[num_active] = {0, 1};
    constexpr float route_weights[num_active] = {0.625f, 0.375f};
    const DeviceId device = DeviceId::rocm(0);
    hipStream_t stream = rocmMoETestStream();

    ScopedEnvOverride perf_stats_env("LLAMINAR_PERF_STATS_JSON", "1");
    PerfStatsCollector::reset();

    ROCmMoEKernel moe_kernel(0);
    static_cast<ITensorKernel &>(moe_kernel).setGPUStream(stream);
    auto moe_workspace = bindDefaultMoEWorkspace(
        moe_kernel,
        /*max_seq_len=*/1,
        d_model,
        intermediate,
        num_experts,
        num_active);

    std::vector<std::unique_ptr<TensorBase>> weight_tensors;
    std::vector<std::unique_ptr<rocm::ROCmPackedWeights>> packed_weights;
    std::vector<std::unique_ptr<rocm::ROCmQuantisedGemmKernel>> down_kernels;
    for (int expert = 0; expert < num_experts; ++expert)
    {
        std::unique_ptr<TensorBase> weights;
        if (expert == 0)
        {
            weights = TestTensorFactory::createQ4_KRandom(
                {static_cast<size_t>(d_model),
                 static_cast<size_t>(intermediate)});
        }
        else
        {
            weights = TestTensorFactory::createQ5_KRandom(
                {static_cast<size_t>(d_model),
                 static_cast<size_t>(intermediate)});
        }
        injectNonZeroKQuantMins(weights.get());

        auto packed = std::make_unique<rocm::ROCmPackedWeights>();
        ASSERT_TRUE(rocm::packWeightsToROCm(weights.get(), *packed));
        auto kernel = std::make_unique<rocm::ROCmQuantisedGemmKernel>(
            packed.get(), 0);
        kernel->setGPUStream(stream);
        weight_tensors.push_back(std::move(weights));
        packed_weights.push_back(std::move(packed));
        down_kernels.push_back(std::move(kernel));
    }

    WorkspaceRequirements gemm_requirements;
    for (const auto &kernel : down_kernels)
    {
        gemm_requirements.merge(
            kernel->getWorkspaceRequirements(1, d_model, intermediate));
    }
    auto gemm_workspace = std::make_unique<DeviceWorkspaceManager>(
        device, 64 * 1024 * 1024);
    ASSERT_TRUE(gemm_workspace->allocate(gemm_requirements));
    for (auto &kernel : down_kernels)
    {
        kernel->bindWorkspace(gemm_workspace.get());
        kernel->prepareWeights();
    }

    std::array<std::shared_ptr<FP32Tensor>, num_active> gates;
    std::array<std::shared_ptr<FP32Tensor>, num_active> ups;
    std::array<ITensor *, num_active> gate_ptrs{};
    std::array<ITensor *, num_active> up_ptrs{};
    for (int route = 0; route < num_active; ++route)
    {
        gates[route] = TestTensorFactory::createFP32Random(
            {1, static_cast<size_t>(intermediate)},
            -1.5f, 1.5f, 8120 + route);
        ups[route] = TestTensorFactory::createFP32Random(
            {1, static_cast<size_t>(intermediate)},
            -1.5f, 1.5f, 8130 + route);
        ASSERT_TRUE(gates[route]->ensureOnDevice(device, stream));
        ASSERT_TRUE(ups[route]->ensureOnDevice(device, stream));
        gate_ptrs[route] = gates[route].get();
        up_ptrs[route] = ups[route].get();
    }

    auto serial_output = TestTensorFactory::createFP32(
        {1, static_cast<size_t>(d_model)});
    auto table_output = TestTensorFactory::createFP32(
        {1, static_cast<size_t>(d_model)});
    auto runtime_output = TestTensorFactory::createFP32(
        {1, static_cast<size_t>(d_model)});
    ASSERT_TRUE(serial_output->ensureOnDevice(device, stream));
    ASSERT_TRUE(table_output->ensureOnDevice(device, stream));
    ASSERT_TRUE(runtime_output->ensureOnDevice(device, stream));
    moe_kernel.zeroBuffer(
        serial_output.get(), static_cast<size_t>(d_model) * sizeof(float));
    moe_kernel.zeroBuffer(
        table_output.get(), static_cast<size_t>(d_model) * sizeof(float));
    moe_kernel.zeroBuffer(
        runtime_output.get(), static_cast<size_t>(d_model) * sizeof(float));

    std::array<std::shared_ptr<FP32Tensor>, num_active> route_outputs;
    for (int route = 0; route < num_active; ++route)
    {
        route_outputs[route] = TestTensorFactory::createFP32(
            {1, static_cast<size_t>(d_model)});
        ASSERT_TRUE(route_outputs[route]->ensureOnDevice(device, stream));
        ASSERT_TRUE(down_kernels[route]->multiply_tensor_with_fused_swiglu(
            gates[route].get(),
            ups[route].get(),
            route_outputs[route].get(),
            /*M=*/1,
            d_model,
            intermediate));
        moe_kernel.weightedAddFromTensors(
            serial_output.get(),
            route_outputs[route].get(),
            route_weights[route],
            d_model);
    }

    std::vector<DeviceNativeVNNIMatrixDesc> descriptors(num_experts);
    for (int expert = 0; expert < num_experts; ++expert)
    {
        ASSERT_TRUE(
            down_kernels[expert]->exportNativeVNNIMatrixDesc(
                descriptors[expert]));
    }
    ASSERT_NE(descriptors[0].codebook_id, descriptors[1].codebook_id);
    ASSERT_NE(
        descriptors[0].arithmeticPolicyCodebookId(),
        descriptors[1].arithmeticPolicyCodebookId());

    const int table_id = moe_kernel.uploadGroupedExpertDownDescriptorTable(
        descriptors.data(), num_experts, d_model, intermediate);
    ASSERT_GE(table_id, 0);
    ASSERT_TRUE(moe_kernel.groupedExpertDownDecodeFromTable(
        gate_ptrs.data(),
        up_ptrs.data(),
        expert_ids,
        route_weights,
        table_id,
        num_active,
        table_output.get(),
        d_model,
        intermediate));

    DeviceMoELayerRuntime host_runtime =
        makeAllLocalRuntime(num_experts, num_active);
    populateRuntimeDescriptors(
        host_runtime, nullptr, nullptr, &descriptors);
    for (int route = 0; route < num_active; ++route)
    {
        host_runtime.topk_expert_ids[route] = expert_ids[route];
        host_runtime.topk_weights[route] = route_weights[route];
    }
    DeviceMoELayerRuntime *device_runtime = nullptr;
    ASSERT_EQ(
        hipMalloc(
            reinterpret_cast<void **>(&device_runtime),
            sizeof(DeviceMoELayerRuntime)),
        hipSuccess);
    ASSERT_EQ(
        hipMemcpyAsync(
            device_runtime,
            &host_runtime,
            sizeof(host_runtime),
            hipMemcpyHostToDevice,
            stream),
        hipSuccess);
    ASSERT_TRUE(moe_kernel.groupedExpertDownDecodeFromRuntime(
        gate_ptrs.data(),
        up_ptrs.data(),
        device_runtime,
        table_id,
        num_active,
        runtime_output.get(),
        d_model,
        intermediate));
    ASSERT_EQ(hipStreamSynchronize(stream), hipSuccess);
    ASSERT_EQ(hipFree(device_runtime), hipSuccess);

    ASSERT_TRUE(serial_output->ensureOnHost(stream));
    ASSERT_TRUE(table_output->ensureOnHost(stream));
    ASSERT_TRUE(runtime_output->ensureOnHost(stream));
    expectBitwiseVerifierRowsEqual(
        "ROCm mixed-codebook table down decode vs serial rows",
        table_output->data(),
        serial_output->data(),
        static_cast<size_t>(d_model),
        static_cast<size_t>(d_model));
    expectBitwiseVerifierRowsEqual(
        "ROCm mixed-codebook runtime down decode vs serial rows",
        runtime_output->data(),
        serial_output->data(),
        static_cast<size_t>(d_model),
        static_cast<size_t>(d_model));

    const auto records = PerfStatsCollector::snapshot(
        {"kernel.rocm_moe_descriptor_local_decode_calls"});
    bool saw_static_mixed = false;
    bool saw_runtime_mixed = false;
    for (const auto &record : records)
    {
        const auto projection = record.tags.find("projection");
        const auto source = record.tags.find("descriptor_source");
        const auto table_codebook = record.tags.find("table_codebook");
        if (projection == record.tags.end() || projection->second != "down" ||
            source == record.tags.end() ||
            table_codebook == record.tags.end() ||
            table_codebook->second != "255")
        {
            continue;
        }
        saw_static_mixed |= source->second == "static_table";
        saw_runtime_mixed |= source->second == "runtime_bank";
    }
    EXPECT_TRUE(saw_static_mixed);
    EXPECT_TRUE(saw_runtime_mixed);
}

/**
 * @brief Compare grouped gate/up decode entrypoints with serial projection.
 *
 * The weight factory may either accept `(rows, columns)` for a homogeneous
 * table or `(expert_id, is_gate, rows, columns)` when a test needs a
 * heterogeneous descriptor table.  Keeping both variants in one harness makes
 * mixed-codebook coverage inherit the same serial, host-routed, device-routed,
 * and runtime-bank byte checks as every single-format case.
 *
 * @tparam WeightFactory Callable returning one owned quantized weight tensor.
 * @param label Diagnostic prefix used for byte-comparison failures.
 * @param create_weights Factory for gate and up projection weights.
 * @param require_mixed_descriptor_policy Whether to require mixed source
 *        arithmetic policies and their production PerfStats evidence.
 */
template <typename WeightFactory>
void runGroupedExpertGateUpDecodeFormatMatch(
    const char *label,
    WeightFactory create_weights,
    bool require_mixed_descriptor_policy = false)
{
    const int d_model = 256;
    const int intermediate = 128;
    const int num_experts = 8;
    const int num_active = 4;
    const int expert_ids[num_active] = {2, 7, 3, 5};
    const DeviceId device = DeviceId::rocm(0);
    hipStream_t stream = rocmMoETestStream();

    std::unique_ptr<ScopedEnvOverride> perf_stats_env;
    if (require_mixed_descriptor_policy)
    {
        perf_stats_env = std::make_unique<ScopedEnvOverride>(
            "LLAMINAR_PERF_STATS_JSON", "1");
        PerfStatsCollector::reset();
    }

    auto make_weights = [&](int expert_id, bool is_gate)
    {
        if constexpr (std::is_invocable_v<
                          WeightFactory &,
                          int,
                          bool,
                          size_t,
                          size_t>)
        {
            return create_weights(
                expert_id,
                is_gate,
                static_cast<size_t>(intermediate),
                static_cast<size_t>(d_model));
        }
        else
        {
            return create_weights(
                static_cast<size_t>(intermediate),
                static_cast<size_t>(d_model));
        }
    };

    ROCmMoEKernel moe_kernel(0);
    static_cast<ITensorKernel &>(moe_kernel).setGPUStream(stream);
    auto moe_kernel_workspace = bindDefaultMoEWorkspace(moe_kernel);

    std::vector<std::unique_ptr<TensorBase>> gate_weight_tensors;
    std::vector<std::unique_ptr<TensorBase>> up_weight_tensors;
    std::vector<std::unique_ptr<rocm::ROCmPackedWeights>> gate_packed_weights;
    std::vector<std::unique_ptr<rocm::ROCmPackedWeights>> up_packed_weights;
    std::vector<std::unique_ptr<rocm::ROCmQuantisedGemmKernel>> gate_kernels;
    std::vector<std::unique_ptr<rocm::ROCmQuantisedGemmKernel>> up_kernels;
    gate_weight_tensors.reserve(num_experts);
    up_weight_tensors.reserve(num_experts);
    gate_packed_weights.reserve(num_experts);
    up_packed_weights.reserve(num_experts);
    gate_kernels.reserve(num_experts);
    up_kernels.reserve(num_experts);

    for (int expert_id = 0; expert_id < num_experts; ++expert_id)
    {
        auto gate_weights = make_weights(expert_id, /*is_gate=*/true);
        auto up_weights = make_weights(expert_id, /*is_gate=*/false);
        auto gate_packed = std::make_unique<rocm::ROCmPackedWeights>();
        auto up_packed = std::make_unique<rocm::ROCmPackedWeights>();
        ASSERT_TRUE(rocm::packWeightsToROCm(gate_weights.get(), *gate_packed))
            << "packWeightsToROCm failed for " << label << " gate expert " << expert_id;
        ASSERT_TRUE(rocm::packWeightsToROCm(up_weights.get(), *up_packed))
            << "packWeightsToROCm failed for " << label << " up expert " << expert_id;
        ASSERT_FALSE(gate_packed->native_vnni_payload.empty());
        ASSERT_FALSE(up_packed->native_vnni_payload.empty());

        auto gate_kernel = std::make_unique<rocm::ROCmQuantisedGemmKernel>(gate_packed.get(), 0);
        auto up_kernel = std::make_unique<rocm::ROCmQuantisedGemmKernel>(up_packed.get(), 0);
        gate_kernel->setGPUStream(stream);
        up_kernel->setGPUStream(stream);
        gate_weight_tensors.push_back(std::move(gate_weights));
        up_weight_tensors.push_back(std::move(up_weights));
        gate_packed_weights.push_back(std::move(gate_packed));
        up_packed_weights.push_back(std::move(up_packed));
        gate_kernels.push_back(std::move(gate_kernel));
        up_kernels.push_back(std::move(up_kernel));
    }

    auto reqs = gate_kernels[0]->getWorkspaceRequirements(1, intermediate, d_model);
    auto workspace = std::make_unique<DeviceWorkspaceManager>(device, 64 * 1024 * 1024);
    ASSERT_TRUE(workspace->allocate(reqs));
    for (int expert_id = 0; expert_id < num_experts; ++expert_id)
    {
        gate_kernels[expert_id]->bindWorkspace(workspace.get());
        up_kernels[expert_id]->bindWorkspace(workspace.get());
        gate_kernels[expert_id]->prepareWeights();
        up_kernels[expert_id]->prepareWeights();
    }

    auto input = TestTensorFactory::createFP32Random(
        {1, static_cast<size_t>(d_model)}, -2.0f, 2.0f, 900);
    ASSERT_TRUE(input->ensureOnDevice(device, stream));

    std::vector<std::shared_ptr<FP32Tensor>> seq_gate_tensors;
    std::vector<std::shared_ptr<FP32Tensor>> seq_up_tensors;
    std::vector<std::shared_ptr<FP32Tensor>> grouped_gate_tensors;
    std::vector<std::shared_ptr<FP32Tensor>> grouped_up_tensors;
    std::vector<std::shared_ptr<FP32Tensor>> device_gate_tensors;
    std::vector<std::shared_ptr<FP32Tensor>> device_up_tensors;
    std::vector<std::shared_ptr<FP32Tensor>> runtime_gate_tensors;
    std::vector<std::shared_ptr<FP32Tensor>> runtime_up_tensors;
    seq_gate_tensors.reserve(num_active);
    seq_up_tensors.reserve(num_active);
    grouped_gate_tensors.reserve(num_active);
    grouped_up_tensors.reserve(num_active);
    device_gate_tensors.reserve(num_active);
    device_up_tensors.reserve(num_active);
    runtime_gate_tensors.reserve(num_active);
    runtime_up_tensors.reserve(num_active);

    std::vector<ITensorGemm::TensorProjectionDesc> projections;
    projections.reserve(num_active * 2);
    for (int i = 0; i < num_active; ++i)
    {
        auto seq_gate = TestTensorFactory::createFP32({1, static_cast<size_t>(intermediate)});
        auto seq_up = TestTensorFactory::createFP32({1, static_cast<size_t>(intermediate)});
        auto grouped_gate = TestTensorFactory::createFP32({1, static_cast<size_t>(intermediate)});
        auto grouped_up = TestTensorFactory::createFP32({1, static_cast<size_t>(intermediate)});
        auto device_gate = TestTensorFactory::createFP32({1, static_cast<size_t>(intermediate)});
        auto device_up = TestTensorFactory::createFP32({1, static_cast<size_t>(intermediate)});
        auto runtime_gate = TestTensorFactory::createFP32({1, static_cast<size_t>(intermediate)});
        auto runtime_up = TestTensorFactory::createFP32({1, static_cast<size_t>(intermediate)});
        ASSERT_TRUE(seq_gate->ensureOnDevice(device, stream));
        ASSERT_TRUE(seq_up->ensureOnDevice(device, stream));
        ASSERT_TRUE(grouped_gate->ensureOnDevice(device, stream));
        ASSERT_TRUE(grouped_up->ensureOnDevice(device, stream));
        ASSERT_TRUE(device_gate->ensureOnDevice(device, stream));
        ASSERT_TRUE(device_up->ensureOnDevice(device, stream));
        ASSERT_TRUE(runtime_gate->ensureOnDevice(device, stream));
        ASSERT_TRUE(runtime_up->ensureOnDevice(device, stream));

        const int expert_id = expert_ids[i];
        projections.emplace_back(gate_kernels[expert_id].get(), seq_gate.get(), intermediate, nullptr, "gate");
        projections.emplace_back(up_kernels[expert_id].get(), seq_up.get(), intermediate, nullptr, "up");

        seq_gate_tensors.push_back(std::move(seq_gate));
        seq_up_tensors.push_back(std::move(seq_up));
        grouped_gate_tensors.push_back(std::move(grouped_gate));
        grouped_up_tensors.push_back(std::move(grouped_up));
        device_gate_tensors.push_back(std::move(device_gate));
        device_up_tensors.push_back(std::move(device_up));
        runtime_gate_tensors.push_back(std::move(runtime_gate));
        runtime_up_tensors.push_back(std::move(runtime_up));
    }

    ASSERT_TRUE(gate_kernels[expert_ids[0]]->multiply_fused_tensor(
        input.get(), projections, 1, d_model));
    (void)hipDeviceSynchronize();

    std::vector<DeviceNativeVNNIMatrixDesc> gate_descs(num_experts);
    std::vector<DeviceNativeVNNIMatrixDesc> up_descs(num_experts);
    for (int expert_id = 0; expert_id < num_experts; ++expert_id)
    {
        ASSERT_TRUE(gate_kernels[expert_id]->exportNativeVNNIMatrixDesc(gate_descs[expert_id]));
        ASSERT_TRUE(up_kernels[expert_id]->exportNativeVNNIMatrixDesc(up_descs[expert_id]));
        ASSERT_EQ(gate_descs[expert_id].n, intermediate);
        ASSERT_EQ(gate_descs[expert_id].k, d_model);
        ASSERT_EQ(up_descs[expert_id].n, intermediate);
        ASSERT_EQ(up_descs[expert_id].k, d_model);
    }

    if (require_mixed_descriptor_policy)
    {
        const uint8_t first_gate_policy =
            gate_descs[expert_ids[0]].arithmeticPolicyCodebookId();
        const uint8_t first_up_policy =
            up_descs[expert_ids[0]].arithmeticPolicyCodebookId();
        bool mixed_gate_policy = false;
        bool mixed_up_policy = false;
        for (int route = 1; route < num_active; ++route)
        {
            mixed_gate_policy |=
                gate_descs[expert_ids[route]].arithmeticPolicyCodebookId() !=
                first_gate_policy;
            mixed_up_policy |=
                up_descs[expert_ids[route]].arithmeticPolicyCodebookId() !=
                first_up_policy;
        }
        ASSERT_TRUE(mixed_gate_policy);
        ASSERT_TRUE(mixed_up_policy);
    }

    ITensor *grouped_gate_ptrs[num_active] = {};
    ITensor *grouped_up_ptrs[num_active] = {};
    ITensor *device_gate_ptrs[num_active] = {};
    ITensor *device_up_ptrs[num_active] = {};
    ITensor *runtime_gate_ptrs[num_active] = {};
    ITensor *runtime_up_ptrs[num_active] = {};
    for (int i = 0; i < num_active; ++i)
    {
        grouped_gate_ptrs[i] = grouped_gate_tensors[i].get();
        grouped_up_ptrs[i] = grouped_up_tensors[i].get();
        device_gate_ptrs[i] = device_gate_tensors[i].get();
        device_up_ptrs[i] = device_up_tensors[i].get();
        runtime_gate_ptrs[i] = runtime_gate_tensors[i].get();
        runtime_up_ptrs[i] = runtime_up_tensors[i].get();
    }

    const int table_id = moe_kernel.uploadGroupedExpertGateUpDescriptorTables(
        gate_descs.data(), up_descs.data(), num_experts, d_model, intermediate);
    ASSERT_GE(table_id, 0);

    ASSERT_TRUE(moe_kernel.groupedExpertGateUpDecodeFromTable(
        input.get(), expert_ids, table_id, num_active,
        grouped_gate_ptrs, grouped_up_ptrs, d_model, intermediate));

    auto routing_indices = TestTensorFactory::createFP32({static_cast<size_t>(num_active)});
    for (int i = 0; i < num_active; ++i)
        routing_indices->mutable_data()[i] = static_cast<float>(expert_ids[i]);
    ASSERT_TRUE(routing_indices->ensureOnDevice(device, stream));

    ASSERT_TRUE(moe_kernel.groupedExpertGateUpDecodeFromRouting(
        input.get(), routing_indices.get(), table_id, num_active,
        device_gate_ptrs, device_up_ptrs, d_model, intermediate));

    DeviceMoELayerRuntime host_runtime = makeAllLocalRuntime(num_experts, num_active);
    populateRuntimeDescriptors(host_runtime, &gate_descs, &up_descs, nullptr);
    for (int i = 0; i < num_active; ++i)
        host_runtime.topk_expert_ids[i] = expert_ids[i];
    DeviceMoELayerRuntime *device_runtime = nullptr;
    ASSERT_EQ(hipMalloc(reinterpret_cast<void **>(&device_runtime), sizeof(DeviceMoELayerRuntime)), hipSuccess);
    ASSERT_EQ(hipMemcpy(device_runtime, &host_runtime, sizeof(DeviceMoELayerRuntime), hipMemcpyHostToDevice), hipSuccess);

    ASSERT_TRUE(moe_kernel.groupedExpertGateUpDecodeFromRuntime(
        device_runtime, input.get(), table_id, num_active,
        runtime_gate_ptrs, runtime_up_ptrs, d_model, intermediate));
    ASSERT_EQ(hipStreamSynchronize(stream), hipSuccess);
    ASSERT_EQ(hipFree(device_runtime), hipSuccess);

    for (int i = 0; i < num_active; ++i)
    {
        ASSERT_TRUE(seq_gate_tensors[i]->ensureOnHost(stream));
        ASSERT_TRUE(seq_up_tensors[i]->ensureOnHost(stream));
        ASSERT_TRUE(grouped_gate_tensors[i]->ensureOnHost(stream));
        ASSERT_TRUE(grouped_up_tensors[i]->ensureOnHost(stream));
        ASSERT_TRUE(device_gate_tensors[i]->ensureOnHost(stream));
        ASSERT_TRUE(device_up_tensors[i]->ensureOnHost(stream));
        ASSERT_TRUE(runtime_gate_tensors[i]->ensureOnHost(stream));
        ASSERT_TRUE(runtime_up_tensors[i]->ensureOnHost(stream));

        const float *seq_gate = seq_gate_tensors[i]->data();
        const float *seq_up = seq_up_tensors[i]->data();
        const float *grouped_gate = grouped_gate_tensors[i]->data();
        const float *grouped_up = grouped_up_tensors[i]->data();
        const float *device_gate = device_gate_tensors[i]->data();
        const float *device_up = device_up_tensors[i]->data();
        const float *runtime_gate = runtime_gate_tensors[i]->data();
        const float *runtime_up = runtime_up_tensors[i]->data();

        ASSERT_FALSE(hasNaNOrInf(grouped_gate, intermediate));
        ASSERT_FALSE(hasNaNOrInf(grouped_up, intermediate));
        ASSERT_FALSE(hasNaNOrInf(device_gate, intermediate));
        ASSERT_FALSE(hasNaNOrInf(device_up, intermediate));
        ASSERT_FALSE(hasNaNOrInf(runtime_gate, intermediate));
        ASSERT_FALSE(hasNaNOrInf(runtime_up, intermediate));

        expectBitwiseVerifierRowsEqual(
            (std::string(label) + " table gate decode vs serial row").c_str(),
            grouped_gate,
            seq_gate,
            static_cast<size_t>(intermediate),
            static_cast<size_t>(intermediate));
        expectBitwiseVerifierRowsEqual(
            (std::string(label) + " table up decode vs serial row").c_str(),
            grouped_up,
            seq_up,
            static_cast<size_t>(intermediate),
            static_cast<size_t>(intermediate));
        expectBitwiseVerifierRowsEqual(
            (std::string(label) + " routed gate decode vs serial row").c_str(),
            device_gate,
            seq_gate,
            static_cast<size_t>(intermediate),
            static_cast<size_t>(intermediate));
        expectBitwiseVerifierRowsEqual(
            (std::string(label) + " routed up decode vs serial row").c_str(),
            device_up,
            seq_up,
            static_cast<size_t>(intermediate),
            static_cast<size_t>(intermediate));
        expectBitwiseVerifierRowsEqual(
            (std::string(label) + " runtime gate decode vs serial row").c_str(),
            runtime_gate,
            seq_gate,
            static_cast<size_t>(intermediate),
            static_cast<size_t>(intermediate));
        expectBitwiseVerifierRowsEqual(
            (std::string(label) + " runtime up decode vs serial row").c_str(),
            runtime_up,
            seq_up,
            static_cast<size_t>(intermediate),
            static_cast<size_t>(intermediate));
    }

    if (require_mixed_descriptor_policy)
    {
        const auto records = PerfStatsCollector::snapshot(
            {"kernel.rocm_moe_descriptor_local_decode_calls"});
        bool saw_static_mixed = false;
        bool saw_runtime_mixed = false;
        for (const auto &record : records)
        {
            const auto projection = record.tags.find("projection");
            const auto source = record.tags.find("descriptor_source");
            const auto table_codebook = record.tags.find("table_codebook");
            if (projection == record.tags.end() ||
                projection->second != "gate_up" ||
                source == record.tags.end() ||
                table_codebook == record.tags.end() ||
                table_codebook->second != "255")
            {
                continue;
            }
            saw_static_mixed |= source->second == "static_table";
            saw_runtime_mixed |= source->second == "runtime_bank";
        }
        EXPECT_TRUE(saw_static_mixed);
        EXPECT_TRUE(saw_runtime_mixed);
    }
}

/**
 * @brief Prove mixed gate/up tables preserve each expert's reduction tree.
 *
 * Q4_K and Q5_K select distinct generated serial-M1 policies at N=128 and
 * K=256.  Alternating them by expert forces one captured grouped launch to
 * choose partition counts descriptor by descriptor for both gate and up.
 */
TEST(Test__ROCmMoEKernel,
     MixedCodebookGateUpDescriptorPoliciesMatchSerialDecodeBytes)
{
    SKIP_IF_NO_ROCM();
    runGroupedExpertGateUpDecodeFormatMatch(
        "mixed Q4_K/Q5_K",
        [](int expert_id,
           bool /*is_gate*/,
           size_t rows,
           size_t columns) -> std::unique_ptr<TensorBase>
        {
            std::unique_ptr<TensorBase> tensor;
            if ((expert_id % 2) == 0)
            {
                tensor = TestTensorFactory::createQ4_KRandom(
                    {rows, columns});
            }
            else
            {
                tensor = TestTensorFactory::createQ5_KRandom(
                    {rows, columns});
            }
            injectNonZeroKQuantMins(tensor.get());
            return tensor;
        },
        /*require_mixed_descriptor_policy=*/true);
}

